arguments.command:
# Try with readelf to get symbol table
aarch64-linux-gnu-readelf -Ws /tmp/libmonosgen-2.0.so.dbg | awk '
  $2 ~ /^[0-9a-f]+$/ && $3+0 > 0 {
    addr = strtonum("0x" $2)
    size = strtonum($3)
    name = $NF
    start[NR] = addr; end_a[NR] = addr + size; nm[NR] = name
  }
  END {
    targets[1] = 0x2f4b20; targets[2] = 0x2f4c84; targets[3] = 0x16de04
    for (t = 1; t <= 3; t++) {
      for (i in start) {
        if (targets[t] >= start[i] && targets[t] < end_a[i]) {
          printf "0x%x -> %s+0x%x\n", targets[t], nm[i], targets[t] - start[i]
        }
      }
    }
  }' 2>/dev/null

