# Try NOTYPE and OBJECT too, find nearest function below these addresses
aarch64-linux-gnu-readelf -Ws /tmp/libmonosgen-2.0.so.dbg | awk '
  $2 ~ /^[0-9a-f]+$/ {
    addr = strtonum("0x" $2)
    size = strtonum($3)
    name = $NF
    if ($4 == "FUNC" || ($4 == "NOTYPE" && size > 0)) {
      a[addr] = name; s[addr] = size
    }
  }
  END {
    # Find nearest symbol at or below target
    targets[1] = 0x2f4b20; targets[2] = 0x2f4c84; targets[3] = 0x2c1a40
    n = asorti(a, sorted, "@ind_num_asc")
    for (t = 1; t <= 3; t++) {
      best = 0
      for (i = 1; i <= n; i++) {
        if (sorted[i]+0 <= targets[t]) best = sorted[i]+0
        else break
      }
      if (best > 0)
        printf "0x%x -> %s+0x%x\n", targets[t], a[best], targets[t] - best
    }
  }' 2>/dev/null

