  $2 ~ /^[0-9a-f]+$/ && $4 == "FUNC" {
    addr = strtonum("0x" $2)
    size = strtonum($3)
    name = $NF
    a[addr] = name; s[addr] = size
  }
  END {
    targets[1] = 0x2f4b20; targets[2] = 0x2f4c84
    n = asorti(a, sorted, "@ind_num_asc")
